<link rel="stylesheet" href="/assets/admin-crud.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/admin-crud.css'))?>"><div class="crud-heading"><div><p>PENDAFTARAN ONLINE</p><h1>Daftar kunjungan</h1></div><a class="button" href="/online-registration" target="_blank">Buka formulir publik</a></div><section class="card"><form method="get" class="report-filter"><label>Tanggal kunjungan<input type="date" name="date" value="<?=e($date)?>"></label><label>Status<select name="status"><option value="">Semua status</option><?php foreach(['registered'=>'Terdaftar','checked_in'=>'Sudah check-in','cancelled'=>'Dibatalkan','expired'=>'Kedaluwarsa'] as $value=>$label):?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label><button type="submit">Tampilkan</button></form></section><section class="crud-table-card"><div class="crud-table-wrap"><table><thead><tr><th>Kode</th><th>Pengunjung</th><th>Layanan</th><th>Kontak</th><th>Status</th><th>Nomor antrean</th><th>Dibuat</th></tr></thead><tbody><?php foreach($registrations as $item):?><tr><td><b><?=e($item['registration_code'])?></b></td><td><b><?=e($item['visitor_name'])?></b><?php if($item['identity_number']):?><small class="crud-description"><?=e($item['identity_number'])?></small><?php endif?></td><td><?=e($item['service_name'])?></td><td><?=e($item['phone']?:$item['email']?:'-')?></td><td><span class="crud-status <?=$item['status']==='checked_in'?'is-active':'is-inactive'?>"><?=e(match($item['status']){'registered'=>'Terdaftar','checked_in'=>'Check-in','cancelled'=>'Dibatalkan','expired'=>'Kedaluwarsa',default=>$item['status']})?></span></td><td><?=e($item['ticket_number']??'-')?></td><td><?=e(date('d/m/Y H:i',strtotime($item['created_at'])))?></td></tr><?php endforeach?><?php if(!$registrations):?><tr><td colspan="7">Belum ada pendaftaran pada filter ini.</td></tr><?php endif?></tbody></table></div></section>
